const base = { id: "123e4567-e89b-12d3-a456-426614174000", email: "a@b.com", name: "n", ip: "1.2.3.4", plan: "free", flags: {} };

print("=== A) raw zod3 library: does z.string().ip() accept zone indices? ===");
for (const s of ["fe80::1%eth0", "3d62::9037%1", "::%1", "5ac3::de2a%wlan0", "fe80::1", "1.2.3.4"]) {
  print(JSON.stringify(s), "zod3.string().ip():", zod3.string().ip().safeParse(s).success);
}

print("=== B) ip via the two builds ===");
const ips = ["fe80::1%eth0", "3d62::9037%1", "::%1", "5ac3::de2a%wlan0", "2001:db8::ff00:42:8329%25", "fe80::1", "1.2.3.4", "fe80::1%", "%eth0", "fe80::1%eth0%bad", "fe80::1%eth0 ", "::%anything-at-all", "fe80::1%../../etc"];
for (const ip of ips) {
  const o = oracle.parseSignup({ ...base, ip });
  const m = main.parseSignup({ ...base, ip });
  print(JSON.stringify(ip), "zod3:", o.ok, "now:", m.ok);
}

print("=== C) website: trim only, or full normalization? ===");
const urls = ["https://example.com", "https://example.com/", " https://example.com", "https://example.com\n", "HTTPS://Example.COM/A", "https://example.com:443/a/../b", "https://example.com/p?b=2&a=1#frag", "https://user:pw@example.com", "https://例え.jp", "https://example.com/%7Euser", "mailto:a@b.com", "http://example.com"];
for (const website of urls) {
  const o = oracle.parseSignup({ ...base, website });
  const m = main.parseSignup({ ...base, website });
  print(JSON.stringify(website), "| zod3:", o.ok ? JSON.stringify(o.value.website) : "REJECT", "| now:", m.ok ? JSON.stringify(m.value.website) : "REJECT");
}

print("=== D) config timeoutMs ===");
for (const timeoutMs of [Infinity, -Infinity, NaN, 5000, 1e308, 0.5, 1]) {
  const o = oracle.parseConfig({ hosts: ["1.2.3.4"], timeoutMs });
  const m = main.parseConfig({ hosts: ["1.2.3.4"], timeoutMs });
  print(String(timeoutMs), "zod3:", o.ok ? JSON.stringify(o.value.timeoutMs) : "REJECT " + JSON.stringify(o.problems), "| now:", m.ok ? JSON.stringify(m.value.timeoutMs) : "REJECT " + JSON.stringify(m.problems));
}
print("omitted timeoutMs ->", JSON.stringify(oracle.parseConfig({ hosts: ["1.2.3.4"] })), JSON.stringify(main.parseConfig({ hosts: ["1.2.3.4"] })));

print("=== E) age ===");
for (const age of [12, 13, 130, 9007199254740991, 9007199254740992, 1e21, 1.5]) {
  const o = oracle.parseSignup({ ...base, age });
  const m = main.parseSignup({ ...base, age });
  print(String(age), "zod3:", o.ok, "now:", m.ok);
}

const ip3 = zod3.string().ip();
print('=== F) which zoned forms did zod3 accept? ===');
const addrs = ['fe80::1','fe80::2','3d62::9037','::1','::','2001:db8::1','a644::8654','1.2.3.4','305b:7432:e22d:4c35:1962:71c6:ed4d:69ae'];
const zones = ['eth0','1','25','wlan0'];
for (const a of addrs) {
  let row = [];
  for (const z of zones) row.push(z + '=' + ip3.safeParse(a + '%' + z).success);
  print(a.padEnd(42), 'bare=' + ip3.safeParse(a).success, row.join(' '));
}

print('=== G) junk zones through the merged build (hosts) ===');
for (const h of ['fe80::1%eth0','fe80::1%eth0%bad','fe80::1%eth0 ','fe80::1%../../etc','fe80::1%localhost:8080','::%0']) {
  const o = oracle.parseConfig({hosts:[h]}), n = main.parseConfig({hosts:[h]});
  print(JSON.stringify(h), 'zod3:', o.ok, 'now:', n.ok);
}

const good = { id:'123e4567-e89b-12d3-a456-426614174000', email:'a@b.com', name:'A', ip:'1.2.3.4', plan:'free', flags:{} };
function f(r){ return r.ok ? 'ACCEPT' : Array.from(new Set(r.problems.map(p=>String(p).split(':')[0]))).sort().join(','); }
print('=== H) multi-error signups: are field-set diffs only ip/age? ===');
const cases = [
  {label:'bad email + zoned ip',       obj:{...good, email:'bad', ip:'3d62::9037%1'}},
  {label:'bad email + unsafe age',     obj:{...good, email:'bad', age:1e21}},
  {label:'zoned ip + unsafe age + bad plan', obj:{...good, ip:'::%1', age:9007199254740992, plan:'nope'}},
  {label:'bad id + zoned ip + long name', obj:{...good, id:'xx', ip:'e575::ec0a%en0', name:'x'.repeat(81)}},
  {label:'bad flags + bad prefs + zoned ip', obj:{...good, ip:'dafa::c206%eth0', flags:{a:'no'}, prefs:{theme:'blue', retries:'2'}}},
  {label:'everything bad',             obj:{id:'x', email:'x', name:'', age:1e30, website:'nope', ip:'nope', plan:'x', flags:{a:1}, prefs:{theme:'x', retries:3}}}
];
for (const c of cases) print(c.label.padEnd(42), 'zod3:[' + f(oracle.parseSignup(c.obj)) + ']  now:[' + f(main.parseSignup(c.obj)) + ']');

print('=== I) multi-error configs ===');
const cfgs = [
  {hosts:['1.2.3.4','3d62::9037%1'], port:'abc'},
  {hosts:['nope','3d62::9037%1'], timeoutMs:Infinity},
  {hosts:[], timeoutMs:Infinity},
  {hosts:['nope'], timeoutMs:-1},
  {hosts:['1.2.3.4'], timeoutMs:Infinity, port:'9'}
];
for (const c of cfgs) print(JSON.stringify(c).padEnd(56), 'zod3:[' + f(oracle.parseConfig(c)) + ']  now:[' + f(main.parseConfig(c)) + ']');

const ip3 = zod3.string().ip();
const base = {id:'123e4567-e89b-12d3-a456-426614174000',email:'a@b.com',name:'n',ip:'1.2.3.4',plan:'free',flags:{}};
print('=== J) zod3 zone acceptance by prefix vs merged build ===');
for (const a of ['fe80::1','fe80::2','fe80:0:0:0:0:0:0:1','fe80::abcd:1234','fec0::1','ff02::1','fd00::1','2001:db8::1','::1','1.2.3.4']) {
  print(a.padEnd(22), 'bare=' + ip3.safeParse(a).success, 'zod3 %eth0=' + ip3.safeParse(a+'%eth0').success, 'now %eth0=' + main.parseSignup({...base, ip:a+'%eth0'}).ok);
}
print('');
print('=== K) other restored checks: do the builds still agree? ===');
function cmp(label, patch){
  const a = oracle.parseSignup({...base, ...patch});
  const b = main.parseSignup({...base, ...patch});
  const f = r => r.ok ? 'ACCEPT name=' + JSON.stringify(r.value.name) + ' site=' + JSON.stringify(r.value.website ?? null) : 'reject[' + r.problems.map(p => String(p).split(':')[0]).sort().join(',') + ']';
  print(label.padEnd(30), 'zod3:', f(a), '| now:', f(b), a.ok === b.ok ? '' : ' <-- VERDICT DIFF');
}
cmp('ipv4 + zone', {ip:'1.2.3.4%eth0'});
cmp('zone with spaces', {ip:'fe80::1% eth 0'});
cmp('name 45 emoji (90 utf16)', {name:'\u{1F600}'.repeat(45)});
cmp('name 41 emoji (82 utf16)', {name:'\u{1F600}'.repeat(41)});
cmp('name 80 ascii', {name:'a'.repeat(80)});
cmp('name 81 ascii', {name:'a'.repeat(81)});
cmp('guid v9/variant-c nibbles', {id:'123e4567-e89b-92d3-c456-426614174000'});
cmp('guid uppercase', {id:'123E4567-E89B-12D3-A456-426614174000'});
cmp('guid bad', {id:'not-a-guid'});
cmp('email a@b', {email:'a@b'});
cmp('email unicode local', {email:'é@b.com'});
cmp('url no scheme', {website:'example.com'});
cmp('url tab inside', {website:'https://exa\tmple.com'});
print('');
print('=== L) prefault defaults identical? ===');
print('zod3 ', JSON.stringify(oracle.parseSignup(base)));
print('now  ', JSON.stringify(main.parseSignup(base)));
print('zod3 prefs {} ', JSON.stringify(oracle.parseSignup({...base, prefs:{}})));
print('now  prefs {} ', JSON.stringify(main.parseSignup({...base, prefs:{}})));
print('');
print('=== M) the exact fuzzer host examples ===');
for (const h of ['5ac3::de2a%wlan0','2459::52d2%lo0','7e60::16eb%25','2001:db8::ff00:42:8329%wlan0','fe80::1%eth0']) {
  print(h.padEnd(30), 'zod3 ip():', ip3.safeParse(h).success, '| merged hosts:', main.parseConfig({hosts:[h]}).ok);
}

